from pathlib import Path
import base64

ROOT = Path(r"C:\Users\Shadow\Desktop\Unreal-Agent")
ORCH = ROOT / "core" / "orchestrator.py"
API = ROOT / "app" / "api.py"

orch = ORCH.read_text(encoding="utf-8-sig")
api = API.read_text(encoding="utf-8-sig")

START = "# >>> HEAVY_SPECIALIST_WRAPPER_V3 >>>"
END = "# <<< HEAVY_SPECIALIST_WRAPPER_V3 <<<"

if START in orch and END in orch:
    a = orch.index(START)
    b = orch.index(END, a) + len(END)
    orch = orch[:a].rstrip() + "\n\n" + orch[b:].lstrip()

required = [
    "AVAILABLE_MODELS",
    "FAST_MODEL",
    "REASONING_MODEL",
    "CODER_MODEL",
    "def create_execution_plan(task):",
    "def recovery_review(",
    "def runtime_info():",
]
for token in required:
    if token not in orch:
        raise RuntimeError(f"Required orchestrator marker not found: {token}")

wrapper = base64.b64decode("").decode("utf-8")

cli_marker = 'if __name__ == "__main__":'
pos = orch.find(cli_marker)
if pos < 0:
    raise RuntimeError("Could not find orchestrator CLI marker")

orch = orch[:pos].rstrip() + "\n\n" + wrapper.strip() + "\n\n" + orch[pos:]

if "    HEAVY_MODEL,\n" not in api:
    needle = "    CODER_MODEL,\n"
    if needle not in api:
        raise RuntimeError("Could not find CODER_MODEL import in app/api.py")
    api = api.replace(
        needle,
        "    CODER_MODEL,\n    HEAVY_MODEL,\n    HEAVY_MODEL_AVAILABLE,\n",
        1,
    )

api = api.replace('version="2.0.0"', 'version="3.0.0"', 1)
api = api.replace('"version": "Adaptive API v2"', '"version": "Adaptive API v3"', 1)

if '"heavy": (' not in api:
    needle = '"coder": CODER_MODEL,'
    if needle not in api:
        raise RuntimeError("Could not find coder status field in app/api.py")
    api = api.replace(
        needle,
        '"coder": CODER_MODEL,\n'
        '            "heavy": (\n'
        '                HEAVY_MODEL\n'
        '                if HEAVY_MODEL_AVAILABLE\n'
        '                else None\n'
        '            ),',
        1,
    )

compile(orch, str(ORCH), "exec")
compile(api, str(API), "exec")

ORCH.write_text(orch, encoding="utf-8")
API.write_text(api, encoding="utf-8")

print("HEAVY_WRAPPER_SOURCE_VALID=PASS")
